function validate([input]) {
  if (typeof input !== 'string' || input.length < 1 || input.length > 10000) return 'input needs 1 to 10^4 characters.';
  if (!/^[A-Za-z0-9 .\n\t]*$/.test(input)) return 'Only letters, digits, spaces, dots, newlines and tabs are allowed.';
  let prevDepth = -1, prevIsFile = false;
  for (const line of input.split('\n')) {
    let depth = 0;
    while (line[depth] === '\t') depth++;
    const name = line.slice(depth);
    if (name.length === 0) return 'Every line needs a non-empty name.';
    if (name.includes('\t')) return 'Tabs may only appear at the start of a line.';
    if (depth > prevDepth + 1) return 'A line can be at most one level deeper than the line above it.';
    if (depth === prevDepth + 1 && prevIsFile) return 'A file cannot contain other entries.';
    prevDepth = depth;
    prevIsFile = name.includes('.');
  }
  return null;
}

