function lengthLongestPath(input) {
  const stack = [0];
  let best = 0;
  for (const line of input.split('\n')) {
    let depth = 0;
    while (line[depth] === '\t') {
      depth++;
    }
    const name = line.slice(depth);
    while (stack.length > depth + 1) {
      stack.pop();
    }
    const length = stack[depth] + name.length;
    if (name.includes('.')) {
      best = Math.max(best, length);
    } else {
      stack.push(length + 1);
    }
  }
  return best;
}

