function lengthLongestPath(input) {
  // For every file, walk upward through the lines to find each ancestor directory and spell out the path.
  const lines = input.split('\n').map(line => {
    const depth = line.length - line.replace(/^\t+/, '').length;
    return { depth, name: line.slice(depth) };
  });
  let best = 0;
  lines.forEach((entry, index) => {
    if (!entry.name.includes('.')) return;
    const parts = [entry.name];
    let want = entry.depth - 1;
    for (let k = index - 1; k >= 0 && want >= 0; k--) {
      if (lines[k].depth === want) { parts.unshift(lines[k].name); want--; }
    }
    best = Math.max(best, parts.join('/').length);
  });
  return best;
}

