function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  const word = (max, spaces) => {
    let text = '';
    const n = 1 + pick(max);
    for (let i = 0; i < n; i++) text += spaces && rand() < 0.15 ? ' ' : letters[pick(letters.length)];
    return text;
  };
  const large = size === 'large';
  const lines = [];
  let total = 0, depth = -1, isFile = false;
  const fileChance = rand() < 0.2 ? 0 : 0.2 + rand() * 0.4;
  const maxLines = large ? Infinity : 1 + pick(8);
  while (lines.length < maxLines) {
    const deepest = isFile ? depth : depth + 1;
    // Going one level deeper is favoured so that paths grow long.
    const next = rand() < 0.5 ? deepest : pick(deepest + 1);
    const file = rand() < fileChance;
    const name = file ? word(large ? 12 : 4, true) + '.' + word(large ? 4 : 3, false) : word(large ? 12 : 5, true);
    const line = '\t'.repeat(next) + name;
    const added = line.length + (lines.length ? 1 : 0);
    if (total + added > (large ? 10000 : 200)) break;
    lines.push(line);
    total += added;
    depth = next;
    isFile = file;
  }
  return [lines.join('\n')];
}
